import { GROUND_Y } from "../config";
import type { LevelDef } from "./level";

/**
 * Chapter 10-2 "The Veil Crown" arena. (10-1 is generated by buildSide in
 * level.ts from its set pieces in config.ts, like every other chapter.)
 *
 * Angelo 2026-10-22: the boss arena must be MUCH bigger and vertical — not
 * just run/dodge/shoot. Two screens wide, three platform tiers, floor
 * trampolines, a spring on top of a stone wall, a lift that rides up and
 * down, and crumbling ledges on the high route over the boss's head.
 * Jump apex ~186px, spring apex ~366px: tier steps are 95–125px so every
 * tier is reachable on foot; springs and the lift are the fast way up.
 */
export function crystalCrownArena(L: LevelDef): LevelDef {
  const G = GROUND_Y;
  const x0 = 1400, x1 = x0 + 2560;
  L.width = x1 + 220;
  L.ground.push({ x0: -200, x1: x1 + 400, y: G });

  // Approach (unchanged).
  L.platforms.push(
    { x: 620, y: G - 90, prop: "plat_log" },
    { x: 980, y: G - 115, prop: "plat_medium" }
  );

  // --- Arena tiers (x offsets from arena.x0) ---
  // Low tier: one jump from the floor.
  L.platforms.push(
    { x: x0 + 260, y: G - 125, prop: "plat_medium" },
    { x: x0 + 760, y: G - 125, prop: "plat_medium" },
    { x: x0 + 1800, y: G - 125, prop: "plat_medium" },
    { x: x0 + 2380, y: G - 125, prop: "plat_medium" }
  );
  // Mid tier.
  L.platforms.push(
    { x: x0 + 520, y: G - 235, prop: "plat_float" },
    { x: x0 + 1560, y: G - 235, prop: "plat_float" },
    { x: x0 + 2230, y: G - 235, prop: "plat_float" }
  );
  // High tier: the run over the boss's head.
  L.platforms.push(
    { x: x0 + 880, y: G - 330, prop: "plat_medium" },
    { x: x0 + 1330, y: G - 330, prop: "plat_medium" },
    { x: x0 + 1980, y: G - 330, prop: "plat_medium" }
  );
  // Crumbling bridges on the high route — don't stand still up there.
  L.crumbles.push({ x: x0 + 1105, y: G - 330 }, { x: x0 + 1865, y: G - 330 });

  // Stone walls: a tall one mid-arena with a spring on top, a short step wall.
  L.walls.push({ x: x0 + 1080, y: G, blocks: 3 }, { x: x0 + 1700, y: G, blocks: 2 });

  // Trampolines: two on the floor, one on top of the tall wall.
  L.springs.push(
    { x: x0 + 420, y: G },
    { x: x0 + 2240, y: G },
    { x: x0 + 1080, y: G - 210 }
  );

  // The lift: rides between the floor and the high tier, mid-arena.
  L.movers.push({ x0: x0 + 1450, y0: G - 20, x1: x0 + 1450, y1: G - 300, period: 6000 });

  L.hearts.push(
    { x: 1050, y: G - 42 },
    { x: x0 + 260, y: G - 125 - 43 },
    { x: x0 + 1330, y: G - 330 - 43 }
  );
  L.arena = { x0, x1 };
  L.portal = { x: (x0 + x1) / 2, y: G };
  return L;
}
